import { BadRequestException } from '@nestjs/common';

export interface PostCursor {
  isUpdating: 0 | 1;
  sortAt: string | null;
  id: string;
}

export function decodePostCursor(token: string): PostCursor {
  try {
    // Accept the standard Base64 format generated by your current code.
    if (
      !token ||
      token.length > 512 ||
      !/^[A-Za-z0-9+/]*={0,2}$/.test(token) ||
      token.length % 4 !== 0
    ) {
      throw new Error('Invalid Base64');
    }

    const decoded = Buffer.from(token, 'base64').toString('utf8');

    // Buffer.from() is permissive, so verify canonical Base64 encoding.
    if (Buffer.from(decoded, 'utf8').toString('base64') !== token) {
      throw new Error('Invalid Base64 encoding');
    }

    const value: unknown = JSON.parse(decoded);

    if (
      typeof value !== 'object' ||
      value === null ||
      Array.isArray(value)
    ) {
      throw new Error('Cursor must be an object');
    }

    const cursor = value as Record<string, unknown>;

    if (
      (cursor.isUpdating !== 0 && cursor.isUpdating !== 1) ||
      typeof cursor.id !== 'string' ||
      !(
        cursor.sortAt === null ||
        (typeof cursor.sortAt === 'string' &&
          cursor.sortAt.length > 0 &&
          !Number.isNaN(Date.parse(cursor.sortAt)))
      )
    ) {
      throw new Error('Invalid cursor fields');
    }

    return {
      isUpdating: cursor.isUpdating,
      sortAt: cursor.sortAt as string | null,
      id: cursor.id,
    };
  } catch (err) {
    console.log('err', err);
    throw new BadRequestException('Invalid afterCursor');
  }
}

export function generatePostCursor(
  isUpdating: 1 | 0,
  sortAt: Date,
  id: string
): string {
  return Buffer
    .from(
      JSON.stringify({
        isUpdating,
        sortAt,
        id,
      }),
      'utf-8'
    )
    .toString('base64');
}
